import { getPortfolioApiBaseUrl } from './portfolioContentService';

const request = async (token, path, options = {}) => {
  const apiBaseUrl = getPortfolioApiBaseUrl();
  if (!apiBaseUrl) throw new Error('REACT_APP_PORTFOLIO_API_URL is not configured.');

  const headers = { Accept: 'application/json' };
  if (token) headers.Authorization = `Bearer ${token}`;
  if (options.body) headers['Content-Type'] = 'application/json';

  const response = await fetch(`${apiBaseUrl}${path}`, {
    method: options.method || 'GET',
    headers,
    body: options.body ? JSON.stringify(options.body) : undefined
  });

  const data = await response.json().catch(() => null);
  if (response.status === 401) {
    const error = new Error('Votre session a expiré. Reconnectez-vous.');
    error.code = 'SESSION_EXPIRED';
    throw error;
  }
  if (!response.ok) {
    throw new Error(data?.message || `Erreur API (${response.status}).`);
  }
  return data;
};

export const portfolioManagerService = {
  loadDrafts: (token) => request(token, '/api/v1/drafts'),
  loadDashboard: (token) => request(token, '/api/v1/dashboard'),
  loadMessages: (token) => request(token, '/api/v1/messages'),
  saveDraft: (token, key, content) => request(token, '/api/v1/drafts', {
    method: 'PUT',
    body: { key, content }
  }),
  publish: (token, key, content = null) => request(token, '/api/v1/publish', {
    method: 'POST',
    body: { key, ...(content ? { content } : {}) }
  }),
  deleteDraft: (token, key) => request(token, `/api/v1/drafts/${encodeURIComponent(key)}`, {
    method: 'DELETE'
  }),
  uploadImage: async (token, file) => {
    const apiBaseUrl = getPortfolioApiBaseUrl();
    if (!apiBaseUrl) throw new Error('REACT_APP_PORTFOLIO_API_URL is not configured.');
    const form = new FormData();
    form.append('image', file);
    const response = await fetch(`${apiBaseUrl}/api/v1/images`, {
      method: 'POST',
      headers: { Accept: 'application/json', Authorization: `Bearer ${token}` },
      body: form
    });
    const data = await response.json().catch(() => null);
    if (!response.ok) throw new Error(data?.message || 'Téléversement impossible.');
    return data;
  },
  changePassword: (token, currentPassword, password) => request(token, '/api/v1/change-password', {
    method: 'POST',
    body: {
      current_password: currentPassword,
      password,
      password_confirmation: password
    }
  }),
  markMessageRead: (token, id) => request(token, `/api/v1/messages/${id}/read`, {
    method: 'PATCH'
  }),
  deleteMessage: (token, id) => request(token, `/api/v1/messages/${id}`, {
    method: 'DELETE'
  }),
  sendMessage: (payload) => request(null, '/api/v1/messages', {
    method: 'POST',
    body: payload
  })
};
