import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import {
  Award, Bell, Briefcase, Code2, ExternalLink, FolderKanban,
  GraduationCap, LayoutDashboard, LogOut, Menu, MessageSquare, Plus,
  Search, Settings, ShieldCheck, Trash2, Upload, UserRound,
  X, Wrench, Share2, Eye, FileText, Check
} from 'lucide-react';
import { Login } from './Login';
import { portfolioAuthService } from '../../shared/services/portfolioAuthService';
import { portfolioManagerService } from '../../shared/services/portfolioManagerService';

const PRIMARY = '#7652FF';
const SECONDARY = '#477BFF';

const NAV_ITEMS = [
  { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
  { id: 'profile', label: 'Informations personnelles', icon: UserRound },
  { id: 'experience', label: 'Expériences', icon: Briefcase },
  { id: 'education', label: 'Formations', icon: GraduationCap },
  { id: 'skills', label: 'Compétences', icon: Code2 },
  { id: 'projects', label: 'Projets', icon: FolderKanban },
  { id: 'certifications', label: 'Certifications', icon: Award },
  { id: 'services', label: 'Services', icon: Wrench },
  { id: 'social', label: 'Réseaux sociaux', icon: Share2 },
  { id: 'messages', label: 'Messages / Contacts', icon: MessageSquare },
  { id: 'settings', label: 'Paramètres', icon: Settings }
];

const emptyProfile = {
  name: '', title: '', description: '', about: '', email: '', phone: '',
  location: '', github: '', linkedin: '', portfolioUrl: '', cvUrl: '', image: ''
};

const StatCard = ({ label, value, icon: Icon, accent = PRIMARY }) => (
  <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} className="rounded-2xl border border-[#292931] bg-[#15151D] p-5">
    <div className="flex items-start justify-between">
      <div className="flex h-11 w-11 items-center justify-center rounded-xl" style={{ background: `${accent}18`, color: accent }}>
        <Icon size={20} />
      </div>
      <span className="rounded-full border border-[#292931] px-2 py-1 text-[10px] text-[#A1A1AA]">Temps réel</span>
    </div>
    <p className="mt-5 text-3xl font-bold">{value ?? 0}</p>
    <p className="mt-1 text-sm text-[#A1A1AA]">{label}</p>
  </motion.div>
);

const DashboardView = ({ dashboard, documents, messages, setActiveView, publishDocument }) => {
  const stats = dashboard.stats || {};
  const cards = [
    ['Projets', stats.projects, FolderKanban, PRIMARY],
    ['Compétences', stats.skills, Code2, SECONDARY],
    ['Expériences', stats.experience, Briefcase, '#A78BFA'],
    ['Formations', stats.education, GraduationCap, '#38BDF8'],
    ['Certifications', stats.certifications, Award, '#F59E0B'],
    ['Messages', stats.messages, MessageSquare, '#F472B6'],
    ['Publiés', stats.published, ShieldCheck, '#22C55E'],
    ['Brouillons', stats.drafts, FileText, '#FB7185']
  ];

  const recent = dashboard.activity || [];
  return (
    <div className="space-y-6">
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
        <div>
          <p className="text-sm text-[#7652FF]">Bonjour Mohammed 👋</p>
          <h2 className="mt-1 text-2xl font-bold sm:text-3xl">Tableau de bord</h2>
          <p className="mt-2 text-sm text-[#A1A1AA]">Source unique : Laravel · Sanctum · Base commune</p>
        </div>
        <button type="button" onClick={() => publishDocument('projects')} className="inline-flex h-11 items-center justify-center gap-2 rounded-xl bg-gradient-to-r from-[#7652FF] to-[#477BFF] px-5 text-sm font-semibold shadow-[0_14px_34px_rgba(118,82,255,.20)]">
          <Upload size={17} />Publier les projets
        </button>
      </div>

      <div className="grid grid-cols-2 gap-3 xl:grid-cols-4">
        {cards.map(([label, value, icon, accent]) => <StatCard key={label} label={label} value={value} icon={icon} accent={accent} />)}
      </div>

      <div className="grid gap-5 xl:grid-cols-[1.35fr_.65fr]">
        <section className="rounded-2xl border border-[#292931] bg-[#15151D] p-5">
          <div className="flex items-center justify-between">
            <div>
              <h3 className="font-bold">Activité récente</h3>
              <p className="mt-1 text-xs text-[#A1A1AA]">Derniers contenus modifiés</p>
            </div>
            <button type="button" onClick={() => setActiveView('projects')} className="text-sm text-[#7652FF]">Voir les projets</button>
          </div>
          <div className="mt-5 space-y-2">
            {recent.length === 0 ? (
              <EmptyState text="Aucune activité enregistrée." />
            ) : recent.map((entry) => (
              <div key={`${entry.key}-${entry.updated_at}`} className="flex items-center gap-3 rounded-xl border border-[#292931] px-4 py-3">
                <div className="flex h-9 w-9 items-center justify-center rounded-lg bg-[#7652FF]/12 text-[#7652FF]"><FileText size={17} /></div>
                <div className="min-w-0 flex-1">
                  <p className="truncate text-sm font-semibold">{entry.label}</p>
                  <p className="text-xs text-[#A1A1AA]">{entry.updated_at ? new Date(entry.updated_at).toLocaleString() : 'Date inconnue'}</p>
                </div>
                <span className={`rounded-full px-2 py-1 text-[10px] ${entry.published ? 'bg-emerald-500/10 text-emerald-400' : 'bg-[#7652FF]/10 text-[#A78BFA]'}`}>
                  {entry.published ? 'Publié' : 'Brouillon'}
                </span>
              </div>
            ))}
          </div>
        </section>

        <section className="rounded-2xl border border-[#292931] bg-[#15151D] p-5">
          <h3 className="font-bold">Actions rapides</h3>
          <div className="mt-4 grid grid-cols-2 gap-3">
            {[
              ['Projet', 'projects', Plus],
              ['Profil', 'profile', UserRound],
              ['Compétence', 'skills', Code2],
              ['Message', 'messages', MessageSquare]
            ].map(([label, view, Icon]) => (
              <button key={label} type="button" onClick={() => setActiveView(view)} className="flex min-h-24 flex-col justify-between rounded-xl border border-[#7652FF]/20 bg-[#7652FF]/[0.07] p-4 text-left text-sm font-semibold hover:border-[#7652FF]/50">
                <Icon size={18} className="text-[#7652FF]" />
                <span>{label}</span>
              </button>
            ))}
          </div>
          <p className="mt-4 text-xs text-[#A1A1AA]">{messages.filter((message) => !message.read_at).length} message(s) non lu(s)</p>
        </section>
      </div>

      <section className="rounded-2xl border border-[#292931] bg-[#15151D] p-5">
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div>
            <h3 className="font-bold">Document principal</h3>
            <p className="mt-1 text-xs text-[#A1A1AA]">{Object.keys(documents).length} clé(s) synchronisée(s)</p>
          </div>
          <a href={`${process.env.PUBLIC_URL || ''}/`} target="_blank" rel="noreferrer" className="inline-flex items-center gap-2 rounded-xl border border-[#292931] px-4 py-2.5 text-sm text-[#A1A1AA] hover:border-[#7652FF] hover:text-white">
            Ouvrir le portfolio <ExternalLink size={15} />
          </a>
        </div>
      </section>
    </div>
  );
};

const EmptyState = ({ text }) => (
  <div className="rounded-xl border border-dashed border-[#292931] px-5 py-10 text-center text-sm text-[#A1A1AA]">{text}</div>
);

const ProfileView = ({ documents, onSave }) => {
  const content = useMemo(() => getDocumentContent(documents, 'profile') || {}, [documents]);
  const [form, setForm] = useState({ ...emptyProfile, ...content });
  useEffect(() => setForm({ ...emptyProfile, ...content }), [content]);

  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));
  const fields = [
    ['name', 'Nom complet'],
    ['title', 'Titre professionnel'],
    ['email', 'Adresse e-mail'],
    ['phone', 'Téléphone'],
    ['location', 'Localisation'],
    ['github', 'GitHub'],
    ['linkedin', 'LinkedIn'],
    ['portfolioUrl', 'URL du portfolio'],
    ['cvUrl', 'CV PDF'],
    ['image', 'Photo de profil']
  ];

  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-2xl font-bold">Informations personnelles</h2>
        <p className="mt-2 text-sm text-[#A1A1AA]">Ces données sont enregistrées sur Laravel et synchronisées avec Android.</p>
      </div>
      <form onSubmit={(event) => { event.preventDefault(); onSave(form); }} className="rounded-2xl border border-[#292931] bg-[#15151D] p-5 sm:p-6">
        <div className="grid gap-4 md:grid-cols-2">
          {fields.map(([key, label]) => (
            <label key={key} className="text-sm font-medium">
              {label}
              <input value={form[key] || ''} onChange={(event) => update(key, event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm font-normal outline-none focus:border-[#7652FF]" />
            </label>
          ))}
        </div>
        <label className="mt-5 block text-sm font-medium">
          Présentation
          <textarea rows="5" value={form.description || ''} onChange={(event) => update('description', event.target.value)} className="mt-2 w-full resize-y rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 py-3 text-sm font-normal outline-none focus:border-[#7652FF]" />
        </label>
        <label className="mt-5 block text-sm font-medium">
          À propos
          <textarea rows="7" value={form.about || ''} onChange={(event) => update('about', event.target.value)} className="mt-2 w-full resize-y rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 py-3 text-sm font-normal outline-none focus:border-[#7652FF]" />
        </label>
        <div className="mt-6 flex justify-end">
          <button type="submit" className="inline-flex h-11 items-center gap-2 rounded-xl bg-gradient-to-r from-[#7652FF] to-[#477BFF] px-5 text-sm font-semibold">
            <Check size={17} />Enregistrer le brouillon
          </button>
        </div>
      </form>
    </div>
  );
};

const ListView = ({ keyName, title, documents, search, onCreate, onEdit, onDelete, onPublish, token, notify }) => {
  const items = getItems(documents, keyName);
  const filtered = useMemo(() => {
    const needle = search.trim().toLowerCase();
    if (!needle) return items;
    return items.filter((item) => JSON.stringify(item).toLowerCase().includes(needle));
  }, [items, search]);

  const primaryKeys = {
    projects: ['title', 'name'],
    skills: ['name', 'title'],
    experience: ['position', 'company'],
    education: ['diploma', 'institution'],
    certifications: ['title', 'issuer'],
    services: ['title', 'name'],
    social: ['name', 'url']
  };
  const secondaryKeys = {
    projects: ['category', 'status'],
    skills: ['category', 'level'],
    experience: ['company', 'start_date'],
    education: ['institution', 'field'],
    certifications: ['issuer', 'date'],
    services: ['description', 'icon'],
    social: ['url', 'icon']
  };

  return (
    <div className="space-y-5">
      <div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-end">
        <div>
          <h2 className="text-2xl font-bold">{title}</h2>
          <p className="mt-2 text-sm text-[#A1A1AA]">{filtered.length} élément(s) affiché(s)</p>
        </div>
        <div className="flex gap-2">
          <button type="button" onClick={onPublish} className="inline-flex h-11 items-center gap-2 rounded-xl border border-[#292931] px-4 text-sm text-[#A1A1AA] hover:border-[#7652FF] hover:text-white">
            <Upload size={16} />Publier
          </button>
          <button type="button" onClick={onCreate} className="inline-flex h-11 items-center gap-2 rounded-xl bg-gradient-to-r from-[#7652FF] to-[#477BFF] px-4 text-sm font-semibold">
            <Plus size={17} />Ajouter
          </button>
        </div>
      </div>

      {filtered.length === 0 ? (
        <EmptyState text={`Aucun élément dans ${title.toLowerCase()}.`} />
      ) : (
        <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">
          {filtered.map((item) => {
            const realIndex = items.indexOf(item);
            const primary = displayValue(item, primaryKeys[keyName]);
            const secondary = displayValue(item, secondaryKeys[keyName]);
            return (
              <motion.article layout key={`${primary}-${realIndex}`} className="rounded-2xl border border-[#292931] bg-[#15151D] p-5">
                <div className="flex items-start justify-between gap-3">
                  <div className="min-w-0">
                    <p className="truncate text-base font-bold">{primary}</p>
                    <p className="mt-1 truncate text-sm text-[#A1A1AA]">{secondary}</p>
                  </div>
                  {keyName === 'projects' && item.featured && (
                    <span className="shrink-0 rounded-full bg-[#7652FF]/12 px-2 py-1 text-[10px] text-[#A78BFA]">Mis en avant</span>
                  )}
                </div>
                {item.description && <p className="mt-4 line-clamp-3 text-sm leading-6 text-[#A1A1AA]">{item.description}</p>}
                {Array.isArray(item.tech) && item.tech.length > 0 && (
                  <div className="mt-4 flex flex-wrap gap-2">
                    {item.tech.slice(0, 5).map((technology) => <span key={technology} className="rounded-full bg-[#7652FF]/10 px-2.5 py-1 text-xs text-[#C4B5FD]">#{technology}</span>)}
                  </div>
                )}
                {keyName === 'skills' && (
                  <div className="mt-4">
                    <div className="mb-2 flex justify-between text-xs text-[#A1A1AA]"><span>Niveau</span><span>{item.level || 0}%</span></div>
                    <div className="h-1.5 overflow-hidden rounded-full bg-[#292931]"><div className="h-full rounded-full bg-gradient-to-r from-[#7652FF] to-[#477BFF]" style={{ width: `${item.level || 0}%` }} /></div>
                  </div>
                )}
                <div className="mt-5 flex items-center gap-2 border-t border-[#292931] pt-4">
                  <button type="button" onClick={() => onEdit(item, realIndex)} className="inline-flex h-9 flex-1 items-center justify-center gap-2 rounded-lg border border-[#292931] text-sm hover:border-[#7652FF]">
                    Modifier
                  </button>
                  <button type="button" onClick={() => onDelete(item, realIndex)} className="flex h-9 w-9 items-center justify-center rounded-lg text-[#A1A1AA] hover:bg-red-500/10 hover:text-red-400" aria-label="Supprimer">
                    <Trash2 size={16} />
                  </button>
                </div>
              </motion.article>
            );
          })}
        </div>
      )}
    </div>
  );
};

const fieldLabel = (keyName, field) => {
  const labels = {
    title: 'Titre',
    name: 'Nom',
    category: 'Catégorie',
    status: 'Statut',
    description: 'Description',
    tech: 'Technologies',
    technologies: 'Technologies',
    github: 'Lien GitHub',
    demo: 'Lien de démonstration',
    date: 'Date',
    start_date: 'Date de début',
    end_date: 'Date de fin',
    featured: 'Projet mis en avant',
    image: 'Image principale',
    gallery: 'Galerie',
    level: 'Niveau',
    icon: 'Icône',
    visible: 'Visible',
    company: 'Entreprise',
    position: 'Poste',
    missions: 'Missions',
    institution: 'Établissement',
    diploma: 'Diplôme',
    field: 'Filière',
    issuer: 'Organisme',
    credential_url: 'Lien de certification',
    features: 'Fonctionnalités',
    url: 'URL'
  };
  return labels[field] || field;
};

const ItemModal = ({ modal, onClose, onSave, token, notify }) => {
  const [item, setItem] = useState(modal.item || {});
  const [uploading, setUploading] = useState(false);
  const fields = {
    projects: ['title', 'category', 'status', 'description', 'tech', 'github', 'demo', 'date', 'featured', 'image', 'gallery'],
    skills: ['name', 'category', 'level', 'icon', 'description', 'visible'],
    experience: ['company', 'position', 'description', 'start_date', 'end_date', 'missions', 'technologies'],
    education: ['institution', 'diploma', 'field', 'date', 'description'],
    certifications: ['title', 'issuer', 'date', 'credential_url', 'image'],
    services: ['title', 'description', 'icon', 'features'],
    social: ['name', 'url', 'icon']
  }[modal.keyName];

  const update = (key, value) => setItem((current) => ({ ...current, [key]: value }));

  const uploadImage = async (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const response = await portfolioManagerService.uploadImage(token, file);
      update(modal.keyName === 'certifications' ? 'image' : 'image', response.url);
      notify('Image téléversée.');
    } catch (error) {
      notify(error.message || 'Téléversement impossible.', 'error');
    } finally {
      setUploading(false);
      event.target.value = '';
    }
  };

  const submit = (event) => {
    event.preventDefault();
    const normalized = { ...item };
    ['tech', 'technologies', 'missions', 'gallery', 'features'].forEach((key) => {
      if (typeof normalized[key] === 'string') {
        normalized[key] = normalized[key].split(',').map((value) => value.trim()).filter(Boolean);
      }
    });
    if (typeof normalized.level === 'string') normalized.level = Number(normalized.level);
    onSave(normalized);
  };

  return (
    <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[80] flex items-center justify-center bg-black/70 p-3 sm:p-6" role="dialog" aria-modal="true">
      <motion.form initial={{ opacity: 0, y: 12, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} exit={{ opacity: 0, y: 8 }} onSubmit={submit} className="max-h-[90vh] w-full max-w-2xl overflow-y-auto rounded-2xl border border-[#292931] bg-[#15151D] shadow-2xl">
        <div className="sticky top-0 z-10 flex items-center justify-between border-b border-[#292931] bg-[#15151D]/95 px-5 py-4 backdrop-blur">
          <h3 className="font-bold">{modal.index === null ? 'Ajouter un élément' : 'Modifier l’élément'}</h3>
          <button type="button" onClick={onClose} className="rounded-lg p-2 text-[#A1A1AA] hover:bg-white/[0.05]"><X size={18} /></button>
        </div>
        <div className="grid gap-4 p-5 md:grid-cols-2">
          {fields.map((field) => {
            if (field === 'featured' || field === 'visible') {
              return (
                <label key={field} className="flex h-11 items-center justify-between rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm">
                  {fieldLabel(modal.keyName, field)}
                  <input type="checkbox" checked={Boolean(item[field])} onChange={(event) => update(field, event.target.checked)} className="accent-[#7652FF]" />
                </label>
              );
            }
            if (field === 'description') {
              return (
                <label key={field} className="text-sm md:col-span-2">
                  {fieldLabel(modal.keyName, field)}
                  <textarea rows="4" value={item[field] || ''} onChange={(event) => update(field, event.target.value)} className="mt-2 w-full resize-y rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 py-3 text-sm outline-none focus:border-[#7652FF]" />
                </label>
              );
            }
            if (field === 'image') {
              return (
                <div key={field} className="text-sm md:col-span-2">
                  {fieldLabel(modal.keyName, field)}
                  <div className="mt-2 flex flex-col gap-2 sm:flex-row">
                    <input value={item[field] || ''} onChange={(event) => update(field, event.target.value)} placeholder="URL" className="h-11 min-w-0 flex-1 rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
                    <label className="inline-flex h-11 cursor-pointer items-center justify-center gap-2 rounded-xl border border-[#292931] px-4 text-sm hover:border-[#7652FF]">
                      <Upload size={16} />{uploading ? 'Envoi...' : 'Téléverser'}
                      <input type="file" accept="image/jpeg,image/png,image/webp" onChange={uploadImage} className="hidden" />
                    </label>
                  </div>
                </div>
              );
            }
            if (['tech', 'technologies', 'missions', 'gallery', 'features'].includes(field)) {
              const value = Array.isArray(item[field]) ? item[field].join(', ') : (item[field] || '');
              return (
                <label key={field} className="text-sm md:col-span-2">
                  {fieldLabel(modal.keyName, field)} <span className="text-xs text-[#A1A1AA]">(séparés par des virgules)</span>
                  <input value={value} onChange={(event) => update(field, event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
                </label>
              );
            }
            const type = field.includes('date') ? 'date' : field === 'level' ? 'number' : 'text';
            return (
              <label key={field} className="text-sm">
                {fieldLabel(modal.keyName, field)}
                {field === 'status' ? (
                  <select value={item[field] || 'draft'} onChange={(event) => update(field, event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]">
                    <option value="draft">Brouillon</option>
                    <option value="published">Publié</option>
                  </select>
                ) : (
                  <input type={type} min={field === 'level' ? 0 : undefined} max={field === 'level' ? 100 : undefined} value={item[field] ?? ''} onChange={(event) => update(field, event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
                )}
              </label>
            );
          })}
        </div>
        <div className="sticky bottom-0 flex justify-end gap-2 border-t border-[#292931] bg-[#15151D]/95 px-5 py-4 backdrop-blur">
          <button type="button" onClick={onClose} className="h-11 rounded-xl border border-[#292931] px-4 text-sm">Annuler</button>
          <button type="submit" className="h-11 rounded-xl bg-gradient-to-r from-[#7652FF] to-[#477BFF] px-5 text-sm font-semibold">Enregistrer</button>
        </div>
      </motion.form>
    </motion.div>
  );
};

const DeleteModal = ({ confirmDelete, onClose, onConfirm }) => (
  <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} className="fixed inset-0 z-[90] flex items-center justify-center bg-black/70 p-4">
    <motion.div initial={{ opacity: 0, y: 10, scale: 0.98 }} animate={{ opacity: 1, y: 0, scale: 1 }} className="w-full max-w-md rounded-2xl border border-[#292931] bg-[#15151D] p-6">
      <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-red-500/10 text-red-400"><Trash2 size={20} /></div>
      <h3 className="mt-5 text-lg font-bold">Confirmer la suppression</h3>
      <p className="mt-2 text-sm leading-6 text-[#A1A1AA]">
        Cet élément sera retiré du brouillon sur Laravel. Confirmez-vous la suppression ?
      </p>
      <div className="mt-6 flex justify-end gap-2">
        <button type="button" onClick={onClose} className="h-11 rounded-xl border border-[#292931] px-4 text-sm">Annuler</button>
        <button type="button" onClick={onConfirm} className="h-11 rounded-xl bg-red-500 px-4 text-sm font-semibold hover:bg-red-400">Supprimer</button>
      </div>
    </motion.div>
  </motion.div>
);

const MessagesView = ({ messages, search, token, notify, onRefresh }) => {
  const filtered = messages.filter((message) => {
    const needle = search.trim().toLowerCase();
    return !needle || `${message.name} ${message.email} ${message.subject || ''} ${message.message}`.toLowerCase().includes(needle);
  });

  const markRead = async (id) => {
    try {
      await portfolioManagerService.markMessageRead(token, id);
      notify('Message marqué comme lu.');
      onRefresh();
    } catch (error) {
      notify(error.message || 'Action impossible.', 'error');
    }
  };

  const deleteMessage = async (id) => {
    try {
      await portfolioManagerService.deleteMessage(token, id);
      notify('Message supprimé.');
      onRefresh();
    } catch (error) {
      notify(error.message || 'Suppression impossible.', 'error');
    }
  };

  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-2xl font-bold">Messages / Contacts</h2>
        <p className="mt-2 text-sm text-[#A1A1AA]">{filtered.length} message(s) dans la boîte</p>
      </div>
      {filtered.length === 0 ? (
        <EmptyState text="Aucun message reçu." />
      ) : (
        <div className="grid gap-3">
          {filtered.map((message) => (
            <article key={message.id} className={`rounded-2xl border p-5 ${message.read_at ? 'border-[#292931] bg-[#15151D]' : 'border-[#7652FF]/35 bg-[#7652FF]/[0.06]'}`}>
              <div className="flex flex-col justify-between gap-4 sm:flex-row">
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <h3 className="font-bold">{message.name}</h3>
                    {!message.read_at && <span className="rounded-full bg-[#7652FF] px-2 py-0.5 text-[10px]">Non lu</span>}
                  </div>
                  <p className="mt-1 text-sm text-[#7652FF]">{message.email}</p>
                  {message.subject && <p className="mt-2 text-sm font-medium">{message.subject}</p>}
                  <p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-[#A1A1AA]">{message.message}</p>
                  <p className="mt-4 text-xs text-[#71717A]">{new Date(message.created_at).toLocaleString()}</p>
                </div>
                <div className="flex shrink-0 gap-2 sm:flex-col">
                  {!message.read_at && <button type="button" onClick={() => markRead(message.id)} className="h-9 rounded-lg border border-[#292931] px-3 text-xs hover:border-[#7652FF]">Marquer lu</button>}
                  <a href={`mailto:${message.email}`} className="flex h-9 items-center justify-center rounded-lg border border-[#292931] px-3 text-xs hover:border-[#7652FF]">Répondre</a>
                  <button type="button" onClick={() => deleteMessage(message.id)} className="h-9 rounded-lg px-3 text-xs text-red-400 hover:bg-red-500/10">Supprimer</button>
                </div>
              </div>
            </article>
          ))}
        </div>
      )}
    </div>
  );
};

const SettingsView = ({ token, notify, onLogout }) => {
  const [currentPassword, setCurrentPassword] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [saving, setSaving] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    if (password.length < 12) {
      notify('Le nouveau mot de passe doit contenir au moins 12 caractères.', 'error');
      return;
    }
    if (password !== confirmPassword) {
      notify('La confirmation ne correspond pas.', 'error');
      return;
    }
    setSaving(true);
    try {
      await portfolioManagerService.changePassword(token, currentPassword, password);
      setCurrentPassword('');
      setPassword('');
      setConfirmPassword('');
      notify('Mot de passe modifié.');
    } catch (error) {
      notify(error.message || 'Modification impossible.', 'error');
    } finally {
      setSaving(false);
    }
  };

  return (
    <div className="space-y-5">
      <div>
        <h2 className="text-2xl font-bold">Paramètres</h2>
        <p className="mt-2 text-sm text-[#A1A1AA]">Sécurité et compte propriétaire.</p>
      </div>
      <form onSubmit={submit} className="max-w-xl rounded-2xl border border-[#292931] bg-[#15151D] p-5 sm:p-6">
        <h3 className="font-bold">Changer le mot de passe</h3>
        <div className="mt-5 space-y-4">
          <label className="block text-sm">Mot de passe actuel
            <input type="password" required value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
          </label>
          <label className="block text-sm">Nouveau mot de passe
            <input type="password" required minLength={12} value={password} onChange={(event) => setPassword(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
          </label>
          <label className="block text-sm">Confirmation
            <input type="password" required value={confirmPassword} onChange={(event) => setConfirmPassword(event.target.value)} className="mt-2 h-11 w-full rounded-xl border border-[#292931] bg-[#0B0B0F] px-3 text-sm outline-none focus:border-[#7652FF]" />
          </label>
        </div>
        <button type="submit" disabled={saving} className="mt-6 h-11 rounded-xl bg-gradient-to-r from-[#7652FF] to-[#477BFF] px-5 text-sm font-semibold disabled:opacity-50">
          {saving ? 'Modification...' : 'Modifier le mot de passe'}
        </button>
      </form>
      <div className="max-w-xl rounded-2xl border border-red-500/20 bg-red-500/[0.03] p-5">
        <h3 className="font-bold">Session</h3>
        <p className="mt-2 text-sm text-[#A1A1AA]">Se déconnecter de cette interface et révoquer le jeton Sanctum.</p>
        <button type="button" onClick={onLogout} className="mt-5 h-11 rounded-xl border border-red-500/30 px-4 text-sm text-red-400 hover:bg-red-500/10">Se déconnecter</button>
      </div>
    </div>
  );
};

const itemDefaults = {
  projects: { title: '', category: '', status: 'draft', description: '', tech: [], github: '', demo: '', date: '', featured: false, image: '', gallery: [] },
  skills: { name: '', category: 'Frontend', level: 80, icon: '', description: '', visible: true },
  experience: { company: '', position: '', description: '', start_date: '', end_date: '', missions: [], technologies: [] },
  education: { institution: '', diploma: '', field: '', date: '', description: '' },
  certifications: { title: '', issuer: '', date: '', credential_url: '', image: '' },
  services: { title: '', description: '', icon: '', features: [] },
  social: { name: '', url: '', icon: '' }
};

const getDocumentContent = (documents, key) => {
  const document = documents?.[key];
  if (!document) return null;
  if (document.draft && typeof document.draft === 'object') return document.draft;
  if (document.published && typeof document.published === 'object') return document.published;
  return null;
};

const getItems = (documents, key) => {
  const content = getDocumentContent(documents, key);
  return Array.isArray(content?.items) ? content.items : [];
};

const displayValue = (item, keys) => {
  for (const key of keys) {
    if (typeof item?.[key] === 'string' && item[key].trim()) return item[key];
  }
  return 'Sans titre';
};

const Dashboard = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [authCheckComplete, setAuthCheckComplete] = useState(false);
  const [authError, setAuthError] = useState('');
  const [token, setToken] = useState('');
  const [activeView, setActiveView] = useState('dashboard');
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [loading, setLoading] = useState(true);
  const [documents, setDocuments] = useState({});
  const [dashboard, setDashboard] = useState({ stats: {}, activity: [] });
  const [messages, setMessages] = useState([]);
  const [search, setSearch] = useState('');
  const [toast, setToast] = useState(null);
  const [modal, setModal] = useState(null);
  const [confirmDelete, setConfirmDelete] = useState(null);

  const notify = useCallback((message, type = 'success') => {
    setToast({ message, type });
  }, []);

  useEffect(() => {
    if (!toast) return undefined;
    const timeout = window.setTimeout(() => setToast(null), 4000);
    return () => window.clearTimeout(timeout);
  }, [toast]);

  const logout = useCallback(async () => {
    try {
      if (token) await portfolioAuthService.logout(token);
    } catch (_) {
      // The local session is cleared even if server revocation fails.
    } finally {
      sessionStorage.removeItem('portfolio_dashboard_token');
      setToken('');
      setIsAuthenticated(false);
      setDocuments({});
      setDashboard({ stats: {}, activity: [] });
      setMessages([]);
    }
  }, [token]);

  useEffect(() => {
    let active = true;
    const savedToken = sessionStorage.getItem('portfolio_dashboard_token');
    if (!savedToken) {
      setAuthCheckComplete(true);
      return undefined;
    }
    portfolioAuthService.verifySession(savedToken).then(() => {
      if (!active) return;
      setToken(savedToken);
      setIsAuthenticated(true);
    }).catch((error) => {
      sessionStorage.removeItem('portfolio_dashboard_token');
      if (active) setAuthError(error instanceof Error ? error.message : 'Session invalide.');
    }).finally(() => {
      if (active) setAuthCheckComplete(true);
    });
    return () => { active = false; };
  }, []);

  const loadData = useCallback(async (showLoading = false) => {
    if (!token) return;
    if (showLoading) setLoading(true);
    try {
      const [draftResponse, dashboardResponse, messageResponse] = await Promise.all([
        portfolioManagerService.loadDrafts(token),
        portfolioManagerService.loadDashboard(token),
        portfolioManagerService.loadMessages(token)
      ]);
      setDocuments(draftResponse.documents || {});
      setDashboard(dashboardResponse);
      setMessages(messageResponse.messages || []);
    } catch (error) {
      if (error.code === 'SESSION_EXPIRED') {
        await logout();
        setAuthError(error.message);
      } else {
        notify(error.message || 'Chargement impossible.', 'error');
      }
    } finally {
      if (showLoading) setLoading(false);
    }
  }, [token, logout, notify]);

  useEffect(() => {
    if (!isAuthenticated || !token) return undefined;
    loadData(true);
    const interval = window.setInterval(() => loadData(false), 15000);
    const onVisible = () => {
      if (document.visibilityState === 'visible') loadData(false);
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearInterval(interval);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [isAuthenticated, token, loadData]);

  const handleLogin = async (email, password) => {
    const nextToken = await portfolioAuthService.login(email, password);
    sessionStorage.setItem('portfolio_dashboard_token', nextToken);
    setToken(nextToken);
    setAuthError('');
    setIsAuthenticated(true);
  };

  const saveDocument = async (key, content) => {
    setLoading(true);
    try {
      await portfolioManagerService.saveDraft(token, key, content);
      notify('Brouillon enregistré.');
      await loadData(false);
    } catch (error) {
      if (error.code === 'SESSION_EXPIRED') await logout();
      notify(error.message || 'Enregistrement impossible.', 'error');
    } finally {
      setLoading(false);
    }
  };

  const publishDocument = async (key) => {
    setLoading(true);
    try {
      await portfolioManagerService.publish(token, key);
      notify('Publication réussie.');
      await loadData(false);
    } catch (error) {
      if (error.code === 'SESSION_EXPIRED') await logout();
      notify(error.message || 'Publication impossible.', 'error');
    } finally {
      setLoading(false);
    }
  };

  if (!authCheckComplete) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-[#0B0B0F]">
        <div className="h-10 w-10 animate-spin rounded-full border-2 border-[#7652FF] border-t-transparent" />
      </div>
    );
  }

  if (!isAuthenticated) return <Login onLogin={handleLogin} initialError={authError} />;

  const activeNav = NAV_ITEMS.find((item) => item.id === activeView);
  const title = activeNav?.label || 'Dashboard';

  return (
    <div className="min-h-screen bg-[#0B0B0F] text-[#F5F5F7]">
      {toast && (
        <motion.div
          initial={{ opacity: 0, y: -12 }}
          animate={{ opacity: 1, y: 0 }}
          className={`fixed right-4 top-4 z-[100] flex max-w-sm items-center gap-3 rounded-xl border px-4 py-3 text-sm shadow-2xl ${
            toast.type === 'error' ? 'border-red-500/30 bg-[#271318]' : 'border-[#7652FF]/40 bg-[#15151D]'
          }`}
        >
          {toast.type === 'error' ? <X size={18} className="text-red-400" /> : <Check size={18} className="text-[#7652FF]" />}
          <span>{toast.message}</span>
        </motion.div>
      )}

      <aside className={`fixed inset-y-0 left-0 z-50 w-[280px] border-r border-[#292931] bg-[#111116] transition-transform lg:translate-x-0 ${mobileMenuOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="flex h-20 items-center gap-3 border-b border-[#292931] px-5">
          <div className="flex h-11 w-11 items-center justify-center rounded-xl bg-gradient-to-br from-[#7652FF] to-[#477BFF] text-sm font-black shadow-[0_12px_30px_rgba(118,82,255,.22)]">MY</div>
          <div className="min-w-0">
            <p className="truncate text-sm font-bold">Portfolio Manager</p>
            <p className="text-xs text-[#A1A1AA]">Administration privée</p>
          </div>
          <button type="button" className="ml-auto rounded-lg p-2 lg:hidden" onClick={() => setMobileMenuOpen(false)} aria-label="Fermer le menu">
            <X size={20} />
          </button>
        </div>
        <nav className="h-[calc(100vh-80px)] overflow-y-auto px-3 py-4">
          {NAV_ITEMS.map((item) => {
            const Icon = item.icon;
            const active = activeView === item.id;
            return (
              <button
                key={item.id}
                type="button"
                onClick={() => {
                  setActiveView(item.id);
                  setMobileMenuOpen(false);
                  setSearch('');
                }}
                className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-left text-sm transition-colors ${
                  active ? 'bg-[#7652FF]/15 text-white' : 'text-[#A1A1AA] hover:bg-white/[0.04] hover:text-white'
                }`}
              >
                <Icon size={18} style={{ color: active ? PRIMARY : undefined }} />
                <span className="truncate">{item.label}</span>
                {item.id === 'messages' && dashboard.stats?.unread_messages > 0 && (
                  <span className="ml-auto rounded-full bg-[#7652FF] px-2 py-0.5 text-[10px] text-white">{dashboard.stats.unread_messages}</span>
                )}
              </button>
            );
          })}
          <button type="button" onClick={logout} className="mt-4 flex w-full items-center gap-3 rounded-xl px-3 py-3 text-sm text-[#A1A1AA] hover:bg-red-500/10 hover:text-red-300">
            <LogOut size={18} />Déconnexion
          </button>
        </nav>
      </aside>

      {mobileMenuOpen && <button type="button" aria-label="Fermer le menu" className="fixed inset-0 z-40 bg-black/60 lg:hidden" onClick={() => setMobileMenuOpen(false)} />}

      <div className="lg:pl-[280px]">
        <header className="sticky top-0 z-30 flex h-20 items-center gap-3 border-b border-[#292931] bg-[#0B0B0F]/95 px-4 backdrop-blur-xl sm:px-6">
          <button type="button" className="rounded-lg border border-[#292931] p-2 lg:hidden" onClick={() => setMobileMenuOpen(true)} aria-label="Ouvrir le menu">
            <Menu size={20} />
          </button>
          <div className="hidden min-w-[180px] md:block">
            <p className="text-xs text-[#A1A1AA]">MY Portfolio Manager</p>
            <h1 className="text-lg font-bold">{title}</h1>
          </div>
          <div className="relative ml-auto w-full max-w-md md:ml-4">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-[#A1A1AA]" size={17} />
            <input
              value={search}
              onChange={(event) => setSearch(event.target.value)}
              placeholder="Rechercher..."
              className="h-11 w-full rounded-xl border border-[#292931] bg-[#15151D] pl-10 pr-4 text-sm outline-none transition-colors placeholder:text-[#71717A] focus:border-[#7652FF]"
            />
          </div>
          <button type="button" className="relative hidden rounded-xl border border-[#292931] p-2.5 text-[#A1A1AA] sm:block" aria-label="Notifications">
            <Bell size={18} />
            {dashboard.stats?.unread_messages > 0 && <span className="absolute right-1.5 top-1.5 h-2 w-2 rounded-full bg-[#7652FF]" />}
          </button>
          <a href={`${process.env.PUBLIC_URL || ''}/`} target="_blank" rel="noreferrer" className="hidden items-center gap-2 rounded-xl border border-[#292931] px-3 py-2.5 text-sm text-[#A1A1AA] hover:border-[#7652FF] hover:text-white md:flex">
            <Eye size={17} />Portfolio
          </a>
          <button type="button" onClick={() => setActiveView('profile')} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-[#7652FF] to-[#477BFF] text-xs font-black" aria-label="Profil administrateur">
            MY
          </button>
        </header>

        <main className="mx-auto max-w-[1500px] p-4 sm:p-6 lg:p-8">
          {loading && <div className="mb-4 h-1 overflow-hidden rounded-full bg-[#15151D]"><div className="h-full w-1/3 animate-pulse rounded-full bg-[#7652FF]" /></div>}
          {activeView === 'dashboard' && (
            <DashboardView
              dashboard={dashboard}
              documents={documents}
              messages={messages}
              setActiveView={setActiveView}
              publishDocument={publishDocument}
            />
          )}
          {activeView === 'profile' && (
            <ProfileView documents={documents} onSave={(content) => saveDocument('profile', content)} />
          )}
          {['projects', 'skills', 'experience', 'education', 'certifications', 'services', 'social'].includes(activeView) && (
            <ListView
              keyName={activeView}
              title={title}
              documents={documents}
              search={search}
              onCreate={() => setModal({ keyName: activeView, item: { ...itemDefaults[activeView] }, index: null })}
              onEdit={(item, index) => setModal({ keyName: activeView, item: { ...item }, index })}
              onDelete={(item, index) => setConfirmDelete({ keyName: activeView, item, index })}
              onPublish={() => publishDocument(activeView)}
              onSave={(keyName, items) => saveDocument(keyName, { items })}
              token={token}
              notify={notify}
            />
          )}
          {activeView === 'messages' && (
            <MessagesView
              messages={messages}
              search={search}
              token={token}
              notify={notify}
              onRefresh={() => loadData(false)}
            />
          )}
          {activeView === 'settings' && (
            <SettingsView token={token} notify={notify} onLogout={logout} />
          )}
        </main>
      </div>

      <AnimatePresence>
        {modal && (
          <ItemModal
            modal={modal}
            onClose={() => setModal(null)}
            onSave={(item) => {
              const keyName = modal.keyName;
              const items = getItems(documents, keyName);
              const nextItems = [...items];
              if (modal.index === null) nextItems.push(item);
              else nextItems[modal.index] = item;
              setModal(null);
              saveDocument(keyName, { items: nextItems });
            }}
            token={token}
            notify={notify}
          />
        )}
      </AnimatePresence>

      <AnimatePresence>
        {confirmDelete && (
          <DeleteModal
            confirmDelete={confirmDelete}
            onClose={() => setConfirmDelete(null)}
            onConfirm={() => {
              const items = getItems(documents, confirmDelete.keyName);
              const nextItems = items.filter((_, index) => index !== confirmDelete.index);
              setConfirmDelete(null);
              saveDocument(confirmDelete.keyName, { items: nextItems });
            }}
          />
        )}
      </AnimatePresence>
    </div>
  );
};

export default Dashboard;
