import React, { useEffect, useState } from 'react';
import { useLanguage } from '../../context/LanguageContext';
import { portfolioData } from '../../data/portfolioData';
import { PageWrapper } from '../../shared/components/PageWrapper';
import { Card, Button } from '../../shared/ui';
import { Lock, KeyRound, Mail } from 'lucide-react';
import { motion } from 'framer-motion';
import { getPortfolioApiBaseUrl } from '../../shared/services/portfolioContentService';

export const Login = ({ onLogin, initialError = '' }) => {
  const { language } = useLanguage();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [error, setError] = useState(initialError);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const t = portfolioData.common[language];
  const apiIsConfigured = Boolean(getPortfolioApiBaseUrl());

  useEffect(() => {
    setError(initialError);
  }, [initialError]);

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!apiIsConfigured || isSubmitting) return;

    setError('');
    setIsSubmitting(true);
    try {
      await onLogin(email, password);
    } catch (loginError) {
      setError(loginError instanceof Error ? loginError.message : t.loginFailed);
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <PageWrapper>
      <div className="min-h-[70vh] flex items-center justify-center bg-[#0B0B0F] px-4">
        <motion.div
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          className="w-full max-w-md"
        >
          <Card className="p-8 space-y-6 !rounded-2xl !border-[#292931] !bg-[#15151D]">
            <div className="text-center space-y-2">
              <div className="w-16 h-16 bg-[#7652FF]/12 text-[#7652FF] rounded-2xl flex items-center justify-center mx-auto mb-4">
                <Lock size={32} />
              </div>
              <h2 className="text-2xl font-bold text-slate-900 dark:text-white">
                {t.restrictedAccess}
              </h2>
              <p className="text-slate-500 dark:text-slate-400">
                {t.loginPrompt}
              </p>
            </div>

            {!apiIsConfigured && (
              <p role="alert" className="text-amber-700 dark:text-amber-300 text-sm font-medium">
                {t.apiNotConfigured}
              </p>
            )}

            <form onSubmit={handleSubmit} className="space-y-4">
              <div className="space-y-2">
                <label htmlFor="dashboard-email" className="text-sm font-medium text-slate-700 dark:text-slate-300">
                  {t.email}
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Mail size={18} className="text-slate-400" />
                  </div>
                  <input
                    id="dashboard-email"
                    type="email"
                    autoComplete="username"
                    required
                    value={email}
                    onChange={(e) => {
                      setEmail(e.target.value);
                      setError('');
                    }}
                    className="w-full pl-10 pr-4 py-3 bg-[#0B0B0F] border border-[#292931] rounded-xl focus:border-[#7652FF] outline-none transition-all text-[#F5F5F7]"
                    placeholder={t.emailPlaceholder}
                  />
                </div>
              </div>
              <div className="space-y-2">
                <label htmlFor="dashboard-password" className="text-sm font-medium text-slate-700 dark:text-slate-300">
                  {t.passwordLabel}
                </label>
                <div className="relative">
                  <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <KeyRound size={18} className="text-slate-400" />
                  </div>
                  <input
                    id="dashboard-password"
                    type="password"
                    autoComplete="current-password"
                    required
                    value={password}
                    onChange={(e) => {
                      setPassword(e.target.value);
                      if (error) setError('');
                    }}
                    className="w-full pl-10 pr-4 py-3 bg-[#0B0B0F] border border-[#292931] rounded-xl focus:border-[#7652FF] outline-none transition-all text-[#F5F5F7]"
                    placeholder={t.passwordPlaceholder}
                  />
                </div>
                {error && (
                   <p role="alert" className="text-red-500 text-sm font-medium pl-1">{error}</p>
                )}
              </div>

              <Button
                type="submit"
                variant="primary"
                disabled={!apiIsConfigured || isSubmitting}
                className="w-full justify-center"
              >
                {isSubmitting ? t.loggingIn : t.loginButton}
              </Button>
            </form>
          </Card>
        </motion.div>
      </div>
    </PageWrapper>
  );
};
