import { getPortfolioApiBaseUrl } from './portfolioContentService';

const request = async (path, { method = 'GET', token, body } = {}) => {
  const apiBaseUrl = getPortfolioApiBaseUrl();
  if (!apiBaseUrl) {
    throw new Error('REACT_APP_PORTFOLIO_API_URL is not configured.');
  }

  const headers = { Accept: 'application/json' };
  if (body) headers['Content-Type'] = 'application/json';
  if (token) headers.Authorization = `Bearer ${token}`;

  const response = await fetch(`${apiBaseUrl}${path}`, {
    method,
    headers,
    ...(body ? { body: JSON.stringify(body) } : {})
  });
  const data = await response.json();

  if (!response.ok) {
    const message = data && typeof data.message === 'string' ? data.message : null;
    throw new Error(message || `Request failed with status ${response.status}.`);
  }
  if (!data || typeof data !== 'object' || Array.isArray(data)) {
    throw new Error('The API returned an invalid response.');
  }

  return data;
};

export const portfolioAuthService = {
  async login(email, password) {
    const data = await request('/api/v1/login', {
      method: 'POST',
      body: { email, password }
    });

    if (typeof data.token !== 'string' || !data.token) {
      throw new Error('The authentication response did not contain a token.');
    }

    return data.token;
  },

  async verifySession(token) {
    const user = await request('/api/user', { token });
    if (!user || typeof user !== 'object') {
      throw new Error('The authentication response did not contain a user.');
    }
  },

  async logout(token) {
    const data = await request('/api/v1/logout', { method: 'POST', token });
    if (data.logged_out !== true) {
      throw new Error('The server did not confirm the session was revoked.');
    }
  }
};
